bruteForceSolution.code:
function patternIncreasingNumberTriangle(n) {
  let rows = [];
  for (let i = 1; i <= n; i++) {
    let row = '';
    for (let j = 1; j <= i; j++) {
      row += j;
    }
    rows.push(row);
  }
  return rows.join('\n');
}

